// Draw spiral
function drawSpiral(ctx, x, y, r, angle, depth) {
    if (depth === 0) return;

    // Draw arc segment
    ctx.beginPath();
    ctx.arc(x, y, r, angle, angle + Math.PI/2);
    ctx.strokeStyle = '#3a5f8a';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Recursive calls for spiral arms
    drawSpiral(ctx, x + r * Math.cos(angle), y - r * Math.sin(angle), r * 0.7, angle + Math.PI/4, depth - 1);
    drawSpiral(ctx, x - r * Math.sin(angle), y + r * Math.cos(angle), r * 0.7, angle - Math.PI/4, depth - 1);
}

